import { Catalog, Category, ErrorEvent, Identity, PartyIdentification } from '../events';
/**
Description: View the details of a product (e.g. a Product Detail Page). This does not cover the case where a product impression is viewed as part of a list (e.g., a Product Listing Page). If tracking how much time a shopper spends viewing a page it may be followed by a Product View Stop interaction.
*/
export type ProductViewStart = {
    events: Array<Catalog | Identity | PartyIdentification | ErrorEvent>;
}

export class ProductViewStartBuilder {

    private productViewStart: ProductViewStart = {
        events: []
    }

    private catalog!: Catalog;
    private errorEvent!: ErrorEvent;
    private identity!: Identity;
    private partyIdentification!: PartyIdentification;

    public withCatalog(catalog: Catalog) : ProductViewStartBuilder {
        this.catalog = catalog;
        return this;
    }
    public withErrorEvent(errorEvent: ErrorEvent) : ProductViewStartBuilder {
        this.errorEvent = errorEvent;
        return this;
    }
    public withIdentity(identity: Identity) : ProductViewStartBuilder {
        this.identity = identity;
        return this;
    }
    public withPartyIdentification(partyIdentification: PartyIdentification) : ProductViewStartBuilder {
        this.partyIdentification = partyIdentification;
        return this;
    }

    public build() : ProductViewStart {
        if(this.catalog) {
            this.productViewStart.events.push(this.catalog);
        }
        if(this.errorEvent) {
            this.productViewStart.events.push(this.errorEvent);
        }
        if(this.identity) {
            this.productViewStart.events.push(this.identity);
        }
        if(this.partyIdentification) {
            this.productViewStart.events.push(this.partyIdentification);
        }

        return this.productViewStart;
    }
}
